CREATE TABLE "SiteDocument" ("id" TEXT PRIMARY KEY,"slug" TEXT NOT NULL,"locale" TEXT NOT NULL DEFAULT 'en',"kind" TEXT NOT NULL DEFAULT 'page',"title" TEXT NOT NULL,"template" TEXT,"draft" JSONB NOT NULL,"published" JSONB,"version" INTEGER NOT NULL DEFAULT 1,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "SiteDocument_slug_locale_key" ON "SiteDocument"("slug","locale");
CREATE TABLE "SiteDocumentRevision" ("id" TEXT PRIMARY KEY,"documentId" TEXT NOT NULL,"version" INTEGER NOT NULL,"snapshot" JSONB NOT NULL,"actorId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "SiteDocumentRevision_documentId_version_key" ON "SiteDocumentRevision"("documentId","version");
CREATE TABLE "Lead" ("id" TEXT PRIMARY KEY,"submissionId" TEXT NOT NULL UNIQUE,"kind" TEXT NOT NULL,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"payload" JSONB NOT NULL,"status" TEXT NOT NULL DEFAULT 'NEW',"emailStatus" TEXT NOT NULL DEFAULT 'PENDING',"emailError" TEXT,"providerId" TEXT,"attempts" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "LeadThrottle" ("key" TEXT PRIMARY KEY,"count" INTEGER NOT NULL DEFAULT 1,"windowStart" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AgentProposal" ("id" TEXT PRIMARY KEY,"documentId" TEXT NOT NULL,"instruction" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'QUEUED',"proposedChanges" JSONB,"baseVersion" INTEGER NOT NULL,"createdBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
